--
-- Name: accept_invitation(text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.accept_invitation(p_token_hash text, p_display_name text, p_password_hash text) RETURNS TABLE(tenant_slug text, role_key text, person_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE inv app.invitation; pid uuid;
BEGIN
  SELECT * INTO inv FROM app.invitation WHERE token_hash = p_token_hash AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at > now() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'EM007 the invitation is unknown, used, revoked or expired'; END IF;
  SELECT p.id INTO pid FROM app.person p WHERE p.email = inv.email;
  IF pid IS NULL THEN INSERT INTO app.person (email, display_name, password_hash) VALUES (inv.email, p_display_name, p_password_hash) RETURNING id INTO pid; END IF;
  INSERT INTO app.membership AS m (tenant_id, person_id, role_key, site_scope) VALUES (inv.tenant_id, pid, inv.role_key, inv.site_scope)
    ON CONFLICT (tenant_id, person_id, role_key) DO UPDATE SET site_scope = EXCLUDED.site_scope, revoked_at = NULL;
  UPDATE app.invitation i SET accepted_at = now(), accepted_by = pid WHERE i.id = inv.id;
  RETURN QUERY SELECT t.slug, inv.role_key, pid FROM app.tenant t WHERE t.id = inv.tenant_id;
END $$;

--
-- Name: asset_register_entry_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.asset_register_entry_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE last int; clash text;
BEGIN
  IF EXISTS (SELECT 1 FROM app.physical_asset a WHERE a.tenant_id = NEW.tenant_id AND a.id = NEW.asset_id AND a.disposition = 'RETIRED') THEN
    RAISE EXCEPTION 'a retired unit takes no register entry' USING ERRCODE = 'EM009'; END IF;
  SELECT coalesce(max(version), 0) INTO last FROM app.asset_register_entry WHERE tenant_id = NEW.tenant_id AND asset_id = NEW.asset_id;
  IF NEW.version <> last + 1 THEN RAISE EXCEPTION 'register version % does not follow % (written by someone else meanwhile)', NEW.version, last USING ERRCODE = '23505'; END IF;
  SELECT a.code INTO clash FROM app.asset_register_entry e JOIN app.physical_asset a ON a.tenant_id = e.tenant_id AND a.id = e.asset_id
    WHERE e.tenant_id = NEW.tenant_id AND e.asset_id <> NEW.asset_id AND a.disposition = 'IN_SERVICE'
      AND e.version = (SELECT max(version) FROM app.asset_register_entry x WHERE x.tenant_id = e.tenant_id AND x.asset_id = e.asset_id)
      AND ((NEW.hostname IS NOT NULL AND lower(e.hostname) = lower(NEW.hostname)) OR (NEW.ip IS NOT NULL AND e.ip = NEW.ip) OR (NEW.mac IS NOT NULL AND e.mac = NEW.mac))
    LIMIT 1;
  IF clash IS NOT NULL THEN RAISE EXCEPTION 'hostname, address or MAC already current on unit %', clash USING ERRCODE = '23505'; END IF;
  RETURN NEW;
END $$;

