--
-- Name: measurement_approval_only(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.measurement_approval_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'EM006 measurements are never deleted'; END IF;
  IF (NEW.value, NEW.unit, NEW.provenance, NEW.metric, NEW.measured_at, NEW.method, NEW.recorded_by, NEW.instrument_id, NEW.calibration_status, NEW.calibration_due, NEW.location, NEW.source, NEW.uncertainty, NEW.import_id, NEW.import_row)
     IS DISTINCT FROM (OLD.value, OLD.unit, OLD.provenance, OLD.metric, OLD.measured_at, OLD.method, OLD.recorded_by, OLD.instrument_id, OLD.calibration_status, OLD.calibration_due, OLD.location, OLD.source, OLD.uncertainty, OLD.import_id, OLD.import_row) THEN
    RAISE EXCEPTION 'EM006 a measurement is immutable; only its approval state may change'; END IF;
  IF OLD.approval_state <> 'UNREVIEWED' THEN RAISE EXCEPTION 'EM006 an approval decision is final; record a new measurement'; END IF;
  RETURN NEW;
END $$;

--
-- Name: migrate_installations(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.migrate_installations() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE t uuid; p record; a uuid; n int := 0;
BEGIN
  FOR t IN SELECT id FROM app.tenant ORDER BY id LOOP
    PERFORM set_config('app.tenant_id', t::text, true);   -- RLS is forced on the owner too: migrate each tenant under its own policy
    FOR p IN
      SELECT pa.id, pa.category, pa.model FROM app.planned_asset pa
       WHERE pa.tenant_id = t AND pa.removed_at IS NULL AND NOT pa.furniture
         AND pa.lifecycle IN ('INSTALLED_UNVERIFIED', 'COMMISSIONING', 'ACCEPTED', 'OPERATIONAL')
         AND NOT EXISTS (SELECT 1 FROM app.asset_installation i WHERE i.tenant_id = t AND i.position_id = pa.id)
       ORDER BY pa.code
    LOOP
      INSERT INTO app.physical_asset (tenant_id, code, category, manufacturer, model, serial, identity_state, origin)
      VALUES (t, app.next_code('physical_asset', 'AS-'), p.category, NULL, p.model, NULL, 'UNKNOWN', 'MIGRATED') RETURNING id INTO a;
      INSERT INTO app.asset_installation (tenant_id, position_id, asset_id, installed_at, effective_basis, install_reason, installed_by, install_note, correlation_id)
      VALUES (t, p.id, a, now(), 'KNOWN_AS_OF_MIGRATION', 'MIGRATED', NULL, 'in place when migration 0026 ran; the installation date and the unit''s identity are not on record', 'migration-0026');
      n := n + 1;
    END LOOP;
  END LOOP;
  PERFORM set_config('app.tenant_id', '', true);
  RETURN n;
END $$;

