--
-- Name: current_result; Type: VIEW; Schema: app; Owner: -
--

CREATE VIEW app.current_result WITH (security_invoker='true') AS
 SELECT DISTINCT ON (r.tenant_id, r.room_id, r.test_id) r.tenant_id,
    r.room_id,
    r.test_id,
    r.id AS result_id,
    r.state,
    r.evidence_id,
    r.evidence_kind,
    r.recorded_by,
    r.recorded_at,
    v.verified_by,
    v.verified_at,
        CASE
            WHEN ((r.state = 'PASS'::text) AND (v.verified_by IS NOT NULL) AND (v.verified_by <> r.recorded_by)) THEN 'PASS_VERIFIED'::text
            WHEN (r.state = 'PASS'::text) THEN 'PASS_UNVERIFIED'::text
            ELSE r.state
        END AS result_label
   FROM (app.test_result r
     LEFT JOIN app.verification v ON ((v.result_id = r.id)))
  ORDER BY r.tenant_id, r.room_id, r.test_id, r.recorded_at DESC, r.id DESC;

