--
-- Name: measurement; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.measurement (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    room_id uuid NOT NULL,
    test_result_id uuid,
    metric text NOT NULL,
    value numeric NOT NULL,
    unit text NOT NULL,
    method text NOT NULL,
    instrument_id text,
    calibration_status text DEFAULT 'UNKNOWN'::text NOT NULL,
    calibration_due date,
    measured_at timestamp with time zone NOT NULL,
    location text NOT NULL,
    source text NOT NULL,
    provenance text NOT NULL,
    uncertainty numeric,
    uncertainty_unit text,
    approval_state text DEFAULT 'UNREVIEWED'::text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    approval_note text,
    recorded_by uuid NOT NULL,
    recorded_role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    import_id uuid,
    import_row integer,
    CONSTRAINT measurement_approval_state_check CHECK ((approval_state = ANY (ARRAY['UNREVIEWED'::text, 'VERIFIED'::text, 'REJECTED'::text]))),
    CONSTRAINT measurement_calibration_status_check CHECK ((calibration_status = ANY (ARRAY['CALIBRATED'::text, 'EXPIRED'::text, 'UNKNOWN'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT measurement_check CHECK (((provenance <> 'FIELD_MEASURED'::text) OR (instrument_id IS NOT NULL))),
    CONSTRAINT measurement_check1 CHECK (((approval_state <> 'VERIFIED'::text) OR ((provenance = 'FIELD_MEASURED'::text) AND (calibration_status = 'CALIBRATED'::text)))),
    CONSTRAINT measurement_check2 CHECK (((approved_by IS NULL) OR (approved_by <> recorded_by))),
    CONSTRAINT measurement_check3 CHECK (((approval_state = 'UNREVIEWED'::text) = (approved_by IS NULL))),
    CONSTRAINT measurement_import_row CHECK (((import_id IS NULL) = (import_row IS NULL))),
    CONSTRAINT measurement_import_row_check CHECK ((import_row > 0)),
    CONSTRAINT measurement_location_check CHECK (((length(location) >= 1) AND (length(location) <= 120))),
    CONSTRAINT measurement_method_check CHECK (((length(method) >= 2) AND (length(method) <= 120))),
    CONSTRAINT measurement_metric_check CHECK ((metric ~ '^[a-z][a-z0-9_]{1,60}$'::text)),
    CONSTRAINT measurement_provenance_check CHECK ((provenance = ANY (ARRAY['DESIGN_SPECIFIED'::text, 'SIMULATED'::text, 'INFERRED'::text, 'OBSERVED'::text, 'FIELD_MEASURED'::text]))),
    CONSTRAINT measurement_source_check CHECK (((length(source) >= 1) AND (length(source) <= 200))),
    CONSTRAINT measurement_unit_check CHECK (((length(unit) >= 1) AND (length(unit) <= 20)))
);

ALTER TABLE ONLY app.measurement FORCE ROW LEVEL SECURITY;

