    CONSTRAINT measurement_import_check CHECK (((rows_calibrated >= 0) AND (rows_calibrated <= rows_total))),
    CONSTRAINT measurement_import_file_sha256_check CHECK ((file_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT measurement_import_instrument_id_check CHECK (((length(instrument_id) >= 2) AND (length(instrument_id) <= 80))),
    CONSTRAINT measurement_import_instrument_model_check CHECK ((length(instrument_model) <= 120)),
    CONSTRAINT measurement_import_method_check CHECK (((length(method) >= 2) AND (length(method) <= 80))),
    CONSTRAINT measurement_import_rows_total_check CHECK ((rows_total > 0))
);

