--
-- Name: outbox_event; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.outbox_event (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    type text NOT NULL,
    schema_version text NOT NULL,
    aggregate_type text NOT NULL,
    aggregate_id text NOT NULL,
    aggregate_rev integer NOT NULL,
    payload jsonb NOT NULL,
    actor_id uuid,
    correlation_id text NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error text,
    delivered_at timestamp with time zone,
    seq bigint NOT NULL,
    aggregate_seq bigint,
    lease_owner text,
    lease_until timestamp with time zone,
    failure_kind text,
    replay_count integer DEFAULT 0 NOT NULL,
    last_replay_audit_id bigint,
    CONSTRAINT outbox_event_failure_kind_check CHECK ((failure_kind = ANY (ARRAY['TRANSIENT'::text, 'PERMANENT'::text, 'NON_RETRYABLE'::text]))),
    CONSTRAINT outbox_event_lease_check CHECK (((lease_owner IS NULL) = (lease_until IS NULL))),
    CONSTRAINT outbox_event_replay_count_check CHECK ((replay_count >= 0)),
    CONSTRAINT outbox_event_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'DELIVERED'::text, 'DEAD_LETTER'::text])))
);

ALTER TABLE ONLY app.outbox_event FORCE ROW LEVEL SECURITY;

--
-- Name: COLUMN outbox_event.aggregate_seq; Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON COLUMN app.outbox_event.aggregate_seq IS 'Position of the event in its aggregate, in commit order (1, 2, 3 …). Assigned at COMMIT by app.outbox_assign_aggregate_seq; NULL only inside the inserting transaction.';

