-- Name: physical_asset; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.physical_asset (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    code text NOT NULL,
    category text NOT NULL,
    manufacturer text,
    model text NOT NULL,
    serial text,
    identity_state text DEFAULT 'UNKNOWN'::text NOT NULL,
    identity_evidence_id uuid,
    identity_by uuid,
    identity_at timestamp with time zone,
    origin text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    disposition text DEFAULT 'IN_SERVICE'::text NOT NULL,
    retired_at timestamp with time zone,
    retired_by uuid,
    retired_role text,
    retirement_reason text,
    retirement_note text,
    retirement_correlation_id text,
    CONSTRAINT physical_asset_category_check CHECK (((length(category) >= 1) AND (length(category) <= 40))),
    CONSTRAINT physical_asset_code_check CHECK ((code ~ '^AS-[0-9]{4,10}$'::text)),
    CONSTRAINT physical_asset_creator CHECK (((origin = 'MIGRATED'::text) OR (created_by IS NOT NULL))),
    CONSTRAINT physical_asset_disposition_check CHECK ((disposition = ANY (ARRAY['IN_SERVICE'::text, 'RETIRED'::text]))),
    CONSTRAINT physical_asset_evidenced_identity CHECK (((identity_state <> ALL (ARRAY['OBSERVED'::text, 'VERIFIED'::text])) OR (identity_evidence_id IS NOT NULL))),
    CONSTRAINT physical_asset_identity_actor CHECK (((identity_state = 'UNKNOWN'::text) OR ((identity_by IS NOT NULL) AND (identity_at IS NOT NULL)))),
    CONSTRAINT physical_asset_identity_state_check CHECK ((identity_state = ANY (ARRAY['UNKNOWN'::text, 'DECLARED'::text, 'OBSERVED'::text, 'VERIFIED'::text]))),
    CONSTRAINT physical_asset_manufacturer_check CHECK (((manufacturer IS NULL) OR ((length(manufacturer) >= 1) AND (length(manufacturer) <= 120)))),
    CONSTRAINT physical_asset_model_check CHECK (((length(model) >= 1) AND (length(model) <= 120))),
    CONSTRAINT physical_asset_origin_check CHECK ((origin = ANY (ARRAY['MIGRATED'::text, 'INSTALLATION_RECORD'::text, 'REGISTERED'::text]))),
    CONSTRAINT physical_asset_retirement_complete CHECK ((((disposition = 'RETIRED'::text) = (retired_at IS NOT NULL)) AND ((disposition = 'RETIRED'::text) = (retired_by IS NOT NULL)) AND ((disposition = 'RETIRED'::text) = (retirement_reason IS NOT NULL)) AND ((disposition = 'RETIRED'::text) = (retirement_correlation_id IS NOT NULL)))),
    CONSTRAINT physical_asset_retirement_note_check CHECK (((retirement_note IS NULL) OR (length(retirement_note) <= 500))),
    CONSTRAINT physical_asset_retirement_reason_check CHECK (((retirement_reason IS NULL) OR (retirement_reason = ANY (ARRAY['REPLACED'::text, 'FAILED'::text, 'DISPOSED'::text, 'RETURNED_TO_VENDOR'::text, 'LOST'::text])))),
    CONSTRAINT physical_asset_serial_check CHECK (((serial IS NULL) OR ((length(serial) >= 1) AND (length(serial) <= 120)))),
    CONSTRAINT physical_asset_unknown_has_no_serial CHECK (((identity_state = 'UNKNOWN'::text) = (serial IS NULL)))
);

