--
-- Name: pilot; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.pilot (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    code text NOT NULL,
    sku text NOT NULL,
    readiness_state text NOT NULL,
    payment_state text DEFAULT 'NOT_STARTED'::text NOT NULL,
    entitlement_state text DEFAULT 'NONE'::text NOT NULL,
    connector_authorization text DEFAULT 'NONE'::text NOT NULL,
    deployment_state text DEFAULT 'NOT_STARTED'::text NOT NULL,
    resume_to text,
    room_limit integer NOT NULL,
    site_limit integer NOT NULL,
    connector_limit integer NOT NULL,
    price_cents integer NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    days integer NOT NULL,
    connector_key text,
    intake jsonb DEFAULT '{}'::jsonb NOT NULL,
    blocking_reasons text[] DEFAULT '{}'::text[] NOT NULL,
    first_verified_source_event_id text,
    activated_at timestamp with time zone,
    ends_at timestamp with time zone,
    converted_at timestamp with time zone,
    converted_plan text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pilot_code_check CHECK ((code ~ '^PLT-[0-9]{4,10}$'::text)),
    CONSTRAINT pilot_connector_authorization_check CHECK ((connector_authorization = ANY (ARRAY['NONE'::text, 'REQUESTED'::text, 'APPROVED'::text, 'DENIED'::text, 'REVOKED'::text]))),
    CONSTRAINT pilot_connector_limit_check CHECK ((connector_limit >= 0)),
    CONSTRAINT pilot_consent_names_connector CHECK (((connector_authorization = 'NONE'::text) OR (connector_key IS NOT NULL))),
    CONSTRAINT pilot_currency_check CHECK ((currency = 'USD'::text)),
    CONSTRAINT pilot_days_check CHECK ((days > 0)),
    CONSTRAINT pilot_deployment_state_check CHECK ((deployment_state = ANY (ARRAY['NOT_STARTED'::text, 'TENANT_READY'::text, 'IDENTITY_APPROVED'::text, 'DISCOVERY_IN_PROGRESS'::text, 'FIRST_SOURCE_VERIFIED'::text, 'ASSETS_RECONCILED'::text, 'PILOT_ACTIVE'::text, 'FIRST_REPORT_DELIVERED'::text, 'REVIEW_READY'::text, 'CONVERSION_APPROVED'::text, 'PILOT_ENDED'::text, 'BLOCKED'::text]))),
    CONSTRAINT pilot_entitlement_needs_payment CHECK (((entitlement_state <> ALL (ARRAY['PROVISIONING'::text, 'ACTIVE'::text])) OR (payment_state = 'VERIFIED'::text))),
    CONSTRAINT pilot_entitlement_state_check CHECK ((entitlement_state = ANY (ARRAY['NONE'::text, 'PROVISIONING'::text, 'ACTIVE'::text, 'SUSPENDED'::text, 'EXPIRED'::text, 'REVOKED'::text]))),
    CONSTRAINT pilot_payment_state_check CHECK ((payment_state = ANY (ARRAY['NOT_STARTED'::text, 'CHECKOUT_STARTED'::text, 'PENDING'::text, 'VERIFIED'::text, 'FAILED'::text, 'REFUNDED'::text, 'DISPUTED'::text]))),
    CONSTRAINT pilot_price_cents_check CHECK ((price_cents >= 0)),
    CONSTRAINT pilot_readiness_state_check CHECK ((readiness_state = ANY (ARRAY['READY_TO_PURCHASE'::text, 'READY_AFTER_CUSTOMER_ACTION'::text, 'REQUIRES_SALES_REVIEW'::text, 'NOT_CURRENTLY_SUPPORTED'::text]))),
    CONSTRAINT pilot_room_limit_check CHECK ((room_limit >= 0)),
    CONSTRAINT pilot_site_limit_check CHECK ((site_limit >= 0)),
    CONSTRAINT pilot_sku_check CHECK ((sku = ANY (ARRAY['PILOT-DISCOVERY'::text, 'PILOT-READONLY'::text, 'PILOT-HARDWARE'::text, 'PILOT-CAMPUS'::text]))),
    CONSTRAINT pilot_source_needs_consent CHECK (((deployment_state <> ALL (ARRAY['DISCOVERY_IN_PROGRESS'::text, 'FIRST_SOURCE_VERIFIED'::text, 'ASSETS_RECONCILED'::text])) OR (connector_authorization = 'APPROVED'::text))),
    CONSTRAINT pilot_verified_source_recorded CHECK (((deployment_state <> 'FIRST_SOURCE_VERIFIED'::text) OR (first_verified_source_event_id IS NOT NULL)))
);

