--
-- Name: proof_claim; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.proof_claim (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_tenant_id uuid NOT NULL,
    claim_id text NOT NULL,
    capability_id text NOT NULL,
    product text NOT NULL,
    world text,
    scope text NOT NULL,
    environment text NOT NULL,
    data_kind text NOT NULL,
    verification_state text NOT NULL,
    implementation_revision text NOT NULL,
    verification_method text,
    verifier_identity text,
    verified_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone,
    source_type text NOT NULL,
    source_freshness_at timestamp with time zone,
    limitations text[] DEFAULT '{}'::text[] NOT NULL,
    claim_text_public text,
    public_approval text DEFAULT 'NOT_REQUESTED'::text NOT NULL,
    owner text NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT proof_approved_is_public_with_wording CHECK (((public_approval <> 'APPROVED'::text) OR ((scope = 'PUBLIC_SANITIZED'::text) AND (claim_text_public IS NOT NULL) AND (length(btrim(claim_text_public)) >= 12) AND (cardinality(limitations) > 0)))),
    CONSTRAINT proof_claim_capability_id_check CHECK (((length(capability_id) >= 2) AND (length(capability_id) <= 160))),
    CONSTRAINT proof_claim_claim_id_check CHECK ((claim_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{3,127}$'::text)),
    CONSTRAINT proof_claim_claim_text_public_check CHECK (((claim_text_public IS NULL) OR (length(claim_text_public) <= 1200))),
    CONSTRAINT proof_claim_data_kind_check CHECK ((data_kind = ANY (ARRAY['SYNTHETIC'::text, 'MODELED'::text, 'IMPORTED'::text, 'LAB_OBSERVED'::text, 'CUSTOMER_OBSERVED'::text]))),
    CONSTRAINT proof_claim_environment_check CHECK ((environment = ANY (ARRAY['dev'::text, 'test'::text, 'staging'::text, 'production'::text, 'synthetic_demo'::text]))),
    CONSTRAINT proof_claim_implementation_revision_check CHECK (((length(implementation_revision) >= 1) AND (length(implementation_revision) <= 120))),
    CONSTRAINT proof_claim_owner_check CHECK (((length(owner) >= 1) AND (length(owner) <= 120))),
    CONSTRAINT proof_claim_product_check CHECK (((length(product) >= 2) AND (length(product) <= 120))),
    CONSTRAINT proof_claim_public_approval_check CHECK ((public_approval = ANY (ARRAY['NOT_REQUESTED'::text, 'PENDING'::text, 'APPROVED'::text, 'REJECTED'::text, 'REVOKED'::text]))),
    CONSTRAINT proof_claim_revision_check CHECK ((revision > 0)),
    CONSTRAINT proof_claim_scope_check CHECK ((scope = ANY (ARRAY['PUBLIC_SANITIZED'::text, 'TENANT'::text, 'STAFF'::text]))),
    CONSTRAINT proof_claim_source_type_check CHECK (((length(source_type) >= 1) AND (length(source_type) <= 200))),
    CONSTRAINT proof_claim_verification_method_check CHECK (((verification_method IS NULL) OR (length(verification_method) <= 400))),
    CONSTRAINT proof_claim_verification_state_check CHECK ((verification_state = ANY (ARRAY['SPECIFIED'::text, 'SYNTHETIC_DEMO'::text, 'IMPLEMENTED_NOT_VERIFIED'::text, 'LAB_VERIFIED'::text, 'CUSTOMER_AUTHORIZED'::text, 'LIVE_OBSERVING'::text, 'DEGRADED'::text, 'BLOCKED'::text, 'REVOKED'::text, 'RELEASED_VERIFIED'::text]))),
    CONSTRAINT proof_claim_verifier_identity_check CHECK (((verifier_identity IS NULL) OR (length(verifier_identity) <= 200))),
    CONSTRAINT proof_claim_world_check CHECK (((world IS NULL) OR (length(world) <= 40))),
    CONSTRAINT proof_demo_holds_synthetic CHECK ((NOT ((environment = 'synthetic_demo'::text) AND (data_kind <> ALL (ARRAY['SYNTHETIC'::text, 'MODELED'::text]))))),
    CONSTRAINT proof_expiry_after_verification CHECK (((expires_at IS NULL) OR (expires_at > verified_at))),
    CONSTRAINT proof_live_is_tenant_and_fresh CHECK (((verification_state <> 'LIVE_OBSERVING'::text) OR ((data_kind = 'CUSTOMER_OBSERVED'::text) AND (scope = 'TENANT'::text) AND (source_freshness_at IS NOT NULL) AND (expires_at IS NOT NULL)))),
    CONSTRAINT proof_synthetic_never_verified CHECK ((NOT ((data_kind = 'SYNTHETIC'::text) AND (verification_state = ANY (ARRAY['LAB_VERIFIED'::text, 'CUSTOMER_AUTHORIZED'::text, 'LIVE_OBSERVING'::text, 'RELEASED_VERIFIED'::text]))))),
    CONSTRAINT proof_verified_names_verifier CHECK (((verification_state <> ALL (ARRAY['LAB_VERIFIED'::text, 'CUSTOMER_AUTHORIZED'::text, 'LIVE_OBSERVING'::text, 'RELEASED_VERIFIED'::text])) OR ((verifier_identity IS NOT NULL) AND (verification_method IS NOT NULL))))
);

