    CONSTRAINT public_lead_email_check CHECK ((((length(email) >= 3) AND (length(email) <= 200)) AND (POSITION(('@'::text) IN (email)) > 1))),
    CONSTRAINT public_lead_kind_check CHECK ((kind = ANY (ARRAY['demo'::text, 'pilot'::text, 'contact'::text]))),
    CONSTRAINT public_lead_message_check CHECK (((length(message) >= 1) AND (length(message) <= 4000))),
    CONSTRAINT public_lead_name_check CHECK (((length(name) >= 1) AND (length(name) <= 120))),
    CONSTRAINT public_lead_notes_check CHECK (((notes IS NULL) OR (length(notes) <= 4000))),
    CONSTRAINT public_lead_organization_check CHECK (((length(organization) >= 1) AND (length(organization) <= 160))),
    CONSTRAINT public_lead_scope_check CHECK (((scope IS NULL) OR (length(scope) <= 80))),
    CONSTRAINT public_lead_status_check CHECK ((status = ANY (ARRAY['NEW'::text, 'ANSWERED'::text, 'SPAM'::text]))),
    CONSTRAINT public_lead_user_agent_check CHECK (((user_agent IS NULL) OR (length(user_agent) <= 300)))
);

