CREATE TABLE app.room (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    building_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    floor integer DEFAULT 1 NOT NULL,
    template text NOT NULL,
    intended_use text DEFAULT ''::text NOT NULL,
    occupancy integer NOT NULL,
    unit text DEFAULT 'm'::text NOT NULL,
    geometry jsonb NOT NULL,
    lifecycle text DEFAULT 'PLANNED'::text NOT NULL,
    classification jsonb,
    approved_class jsonb,
    rev integer DEFAULT 1 NOT NULL,
    approved_revision integer,
    baseline jsonb,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    project_id uuid,
    classification_proposed_by uuid,
    CONSTRAINT room_code_check CHECK ((code ~ '^R-[A-Z0-9-]{3,32}$'::text)),
    CONSTRAINT room_geometry_check CHECK ((jsonb_typeof((geometry -> 'points'::text)) = 'array'::text)),
    CONSTRAINT room_lifecycle_check CHECK ((lifecycle = ANY (ARRAY['PLANNED'::text, 'DESIGN_APPROVED'::text, 'INSTALLATION_PENDING'::text, 'INSTALLED_UNVERIFIED'::text, 'COMMISSIONING'::text, 'ACCEPTED'::text, 'OPERATIONAL'::text]))),
    CONSTRAINT room_name_check CHECK (((length(name) >= 1) AND (length(name) <= 80))),
    CONSTRAINT room_occupancy_check CHECK (((occupancy >= 1) AND (occupancy <= 5000))),
    CONSTRAINT room_rev_check CHECK ((rev >= 1)),
    CONSTRAINT room_unit_check CHECK ((unit = ANY (ARRAY['m'::text, 'ft'::text])))
);

ALTER TABLE ONLY app.room FORCE ROW LEVEL SECURITY;

