    owner_role text,
    owner_id uuid,
    resolution jsonb,
    first_seen_rev integer NOT NULL,
    last_seen_rev integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT room_issue_category_check CHECK ((category = ANY (ARRAY['DESIGN_DEFICIENCY'::text, 'INSTALLATION_COMMISSIONING_DEFICIENCY'::text]))),
    CONSTRAINT room_issue_check CHECK (((state = 'RESOLVED'::text) = (resolution IS NOT NULL))),
    CONSTRAINT room_issue_severity_check CHECK ((severity = ANY (ARRAY['Critical'::text, 'High'::text, 'Medium'::text, 'Low'::text]))),
    CONSTRAINT room_issue_state_check CHECK ((state = ANY (ARRAY['OPEN'::text, 'RESOLVED'::text])))
);

