    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    issue_id uuid NOT NULL,
    code text NOT NULL,
    state text DEFAULT 'OPEN'::text NOT NULL,
    assigned_role text NOT NULL,
    note text DEFAULT ''::text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_by uuid,
    closed_at timestamp with time zone,
    closing_note text,
    work_type text DEFAULT 'break_fix'::text NOT NULL,
    severity text,
    triage jsonb,
    window_from timestamp with time zone,
    window_to timestamp with time zone,
    assigned_to uuid,
    assignment jsonb,
    accepted_at timestamp with time zone,
    preflight jsonb,
    started_at timestamp with time zone,
    evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    verification jsonb,
    reopen_count integer DEFAULT 0 NOT NULL,
    customer_confirmed boolean DEFAULT false NOT NULL,
    CONSTRAINT work_order_assignee_check CHECK (((state <> ALL (ARRAY['ASSIGNED'::text, 'ACCEPTED'::text, 'IN_PROGRESS'::text, 'VERIFYING'::text])) OR (assigned_to IS NOT NULL))),
    CONSTRAINT work_order_check CHECK (((state = 'CLOSED'::text) = (closed_at IS NOT NULL))),
    CONSTRAINT work_order_severity_check CHECK ((severity = ANY (ARRAY['Mission critical'::text, 'High'::text, 'Standard'::text]))),
    CONSTRAINT work_order_state_check CHECK ((state = ANY (ARRAY['OPEN'::text, 'TRIAGED'::text, 'ASSIGNED'::text, 'ACCEPTED'::text, 'IN_PROGRESS'::text, 'VERIFYING'::text, 'RESOLVED'::text, 'CLOSED'::text, 'REOPENED'::text, 'CANCELLED'::text]))),
    CONSTRAINT work_order_window_check CHECK (((window_to IS NULL) OR (window_from IS NULL) OR (window_to >= window_from))),
    CONSTRAINT work_order_work_type_check CHECK ((work_type ~ '^[a-z_]{2,40}$'::text))
);

