--
-- Name: proof_claim proof_public_read; Type: POLICY; Schema: app; Owner: -
--

CREATE POLICY proof_public_read ON app.proof_claim FOR SELECT USING (((current_setting('app.proof_public'::text, true) = 'on'::text) AND (scope = 'PUBLIC_SANITIZED'::text) AND (public_approval = 'APPROVED'::text) AND (verification_state <> ALL (ARRAY['REVOKED'::text, 'BLOCKED'::text]))));

--
-- Name: proof_evidence proof_public_read; Type: POLICY; Schema: app; Owner: -
--

CREATE POLICY proof_public_read ON app.proof_evidence FOR SELECT USING (((current_setting('app.proof_public'::text, true) = 'on'::text) AND approved_derivative AND (EXISTS ( SELECT 1
   FROM app.proof_claim c
  WHERE (c.id = proof_evidence.claim_uuid)))));

